window.SLATE_BANKS = [{"id":"fortios-7.6-admin","vendor":"Fortinet","product":"FortiGate","title":"FortiOS 7.6 Administrator","description":"103-question FortiOS 7.6 Administrator bank from the previous Slate exam trainer.","questionCount":103,"imageCount":50,"source":"previous FortiGate trainer HTML","questions":[{"id":1,"text":"An administrator wants to configure dead peer detection (DPD) on IPsec VPN for detecting dead tunnels. The requirement is that FortiGate sends DPD probes only when there is no inbound traffic. Which DPD mode on FortiGate meets this requirement? (Choose one answer)","options":{"A":"Enabled","B":"On Idle","C":"Disabled","D":"On Demand"},"answer":["D"],"note":"","image":null,"correctCount":1},{"id":2,"text":"Which two statements about equal-cost multi-path (ECMP) configuration on FortiGate are true? (Choose two answers)","options":{"A":"If SD-WAN is enabled, you control the load balancing algorithm with the parameter load-balance-mode.","B":"If SD-WAN is disabled, you can configure the parameter v4-ecmp-mode to volume-based.","C":"If SD-WAN is enabled, you can configure routes with unequal distance and priority values to be part of ECMP","D":"If SD-WAN is disabled, you configure the load balancing algorithm in config system settings."},"answer":["A","D"],"note":"","image":null,"correctCount":2},{"id":3,"text":"You have created a web filter profile named restrict_media-profile with a daily category usage quota. When you are adding the profile to the firewall policy, the restrict_media-profile is not listed in the available web profile drop down. What could be the reason? . (Choose one answer)","options":{"A":"The firewall policy is in no-inspection mode instead of deep-inspection.","B":"The inspection mode in the firewall policy is not matching with web filter profile feature set.","C":"The web filter profile is already referenced in another firewall policy.","D":"The naming convention used in the web filter profile is restricting it in the firewall policy"},"answer":["B"],"note":"","image":null,"correctCount":1},{"id":4,"text":"Refer to the exhibit, As an administrator you have created an IPS profile, but it is not performing as expected. While testing you got the output as shown in the exhibit. What could be the possible reason of the diagnose output shown in the exhibit? (Choose one answer)","options":{"A":"There is no firewall policy configured with an IPS security profile.","B":"FortiGate entered into IPS fail open state.","C":"Administrator entered the command diagnose test application ipsmonitor 5.","D":"Administrator entered the command diagnose test application ipsmonitor 99."},"answer":["A"],"note":"","image":"assets-fortios-q004.jpg","correctCount":1},{"id":5,"text":"Refer to the exhibit. The predefined deep-inspection and custom-deep-inspection profiles exclude some web categories from SSL inspection, as shown in the exhibit. For which two reasons are these web categories exempted? (Choose two answers)","options":{"A":"The FortiGate temporary certificate denies the browser's access to websites that use HTTP Strict Transport Security.","B":"These websites are in an allowlist of reputable domain names maintained by FortiGuard.","C":"The resources utilization is optimized because these websites are in the trusted domain list on FortiGate.","D":"The legal regulation aims to prioritize user privacy and protect sensitive information for these websites."},"answer":["A","D"],"note":"","image":"assets-fortios-q005.jpg","correctCount":2},{"id":6,"text":"Refer to the exhibit. The NOC team connects to the FortiGate GUI with the NOC_Access admin profile. They request that their GUI sessions do not disconnect too early during inactivity. What must the administrator configure to answer this specific request from the NOC team? (Choose one answer)","options":{"A":"Move NOC_Access to the top of the list to ensure all profile settings take effect.","B":"Increase the offline value of the Override Idle Timeout parameter in the NOC_Access admin profile.","C":"Ensure that all NOC_Access users are assigned the super_admin role to guarantee access.","D":"Increase the admintimeout value under config system accprofile NOC_Access."},"answer":["B"],"note":"","image":"assets-fortios-q006.jpg","correctCount":1},{"id":7,"text":"Refer to the exhibit. Based on this partial configuration, what are the two possible outcomes when FortiGate enters conserve mode? (Choose two answers)","options":{"A":"Administrators cannot change the configuration.","B":"FortiGate skips quarantine actions.","C":"Administrators must restart FortiGate to allow new sessions.","D":"FortiGate drops new sessions requiring inspection."},"answer":["A","B"],"note":"","image":"assets-fortios-q007.jpg","correctCount":2},{"id":8,"text":"What is the primary FortiGate election process when the HA override setting is enabled? (Choose one answer)","options":{"A":"Connected monitored ports > Priority > HA uptime > FortiGate serial number","B":"Connected monitored ports > Priority > System uptime > FortiGate serial number","C":"Connected monitored ports > HA uptime > Priority > FortiGate serial number","D":"Connected monitored ports > System uptime > Priority > FortiGate serial number"},"answer":["A"],"note":"","image":null,"correctCount":1},{"id":9,"text":"An administrator wanted to configure an IPS sensor to block traffic that triggers a signature a set number of times during a specific time period. How can the administrator achieve the objective? (Choose one answer)","options":{"A":"Use IPS group signatures, set rate-mode 60.","B":"Use IPS packet logging option with periodical filter option.","C":"Use IPS filter, rate-mode periodical option.","D":"Use IPS signatures, rate-mode periodical option."},"answer":["D"],"note":"","image":null,"correctCount":1},{"id":10,"text":"A FortiGate firewall policy is configured with active authentication, however, the user cannot authenticate when accessing a website. Which protocol must FortiGate allow even though the user cannot authenticate? (Choose one answer)","options":{"A":"LDAP","B":"TACACS+","C":"Kerberos","D":"DNS"},"answer":["D"],"note":"","image":null,"correctCount":1},{"id":11,"text":"Refer to the exhibit, which shows a partial configuration from the remote authentication server. Why does the FortiGate administrator need this configuration? (Choose one answer)","options":{"A":"To authenticate only the Training user group.","B":"To set up a RADIUS server secret.","C":"To authenticate and match the Training OU on the RADIUS server.","D":"To authenticate any FortiGate user groups."},"answer":["A"],"note":"","image":"assets-fortios-q011.jpg","correctCount":1},{"id":12,"text":"Refer to the exhibit, which shows an SD-WAN zone configuration on the FortiGate GUI. Based on the exhibit, which statement is true? (Choose one answer)","options":{"A":"The Underlay zone is the zone by default.","B":"The Underlay zone contains no member.","C":"port2 and port3 are not assigned to a zone.","D":"The virtual-wan-link and overlay zones can be deleted."},"answer":["B"],"note":"","image":"assets-fortios-q012.jpg","correctCount":1},{"id":13,"text":"Which three statements explain a flow-based antivirus profile? (Choose three answers)","options":{"A":"FortiGate buffers the whole file but transmits to the client at the same time.","B":"Flow-based inspection uses a hybrid of the scanning modes available in proxy-based inspection.","C":"If a virus is detected, the last packet is delivered to the client.","D":"Flow-based inspection optimizes performance compared to proxy-based inspection.","E":"The IPS engine handles the process as a standalone."},"answer":["A","B","D"],"note":"Ключ у джерелі: A,B,D. Це типове екзаменаційне формулювання; сучасна FortiOS документація описує stream-based/partial buffering, тому формулювання A варто читати саме в контексті Study Guide.","image":null,"correctCount":3},{"id":14,"text":"Refer to the exhibit. An administrator has configured an Application Overrides for the ABC.Com application signature and set the Action to Allow. This application control profile is then applied to a firewall policy that is scanning all outbound traffic. Logging is enabled in the firewall policy. To test the configuration, the administrator accessed the ABC.Com web site several times. Why are there no logs generated under security logs for ABC.Com? (Choose one answer)","options":{"A":"The ABC.Com Type is set as Application instead of Filter.","B":"The ABC.Com is configured under application profile, which must be configured as a web filter profile.","C":"The ABC.Com Action is set to Allow.","D":"The ABC.Com is hitting the category Excessive-Bandwidth."},"answer":["C"],"note":"","image":"assets-fortios-q014.jpg","correctCount":1},{"id":15,"text":"Which two statements describe characteristics of automation stitches? (Choose two answers)","options":{"A":"Actions involve only devices included in the Security Fabric.","B":"An automation stitch can have multiple triggers.","C":"Multiple actions can run in parallel.","D":"Triggers can involve external connectors."},"answer":["C","D"],"note":"","image":null,"correctCount":2},{"id":16,"text":"Which three statements about SD-WAN performance SLAs are true? (Choose three answers)","options":{"A":"They rely on session loss and jitter.","B":"They can be measured actively or passively.","C":"They are applied in a SD-WAN rule lowest cost strategy.","D":"They monitor the state of the FortiGate device.","E":"All the SLA targets can be configured."},"answer":["B","C","E"],"note":"","image":null,"correctCount":3},{"id":17,"text":"Which two statements are true about an HA cluster? (Choose two answers)","options":{"A":"An HA cluster cannot have both in-band and out-of-band management interfaces at the same time.","B":"Link failover triggers a failover if the administrator sets the interface down on the primary device.","C":"When sniffing the heartbeat interface, the administrator must see the IP address 169.254.0.2.","D":"HA incremental synchronization includes FIB entries and IPsec SAs."},"answer":["B","D"],"note":"","image":null,"correctCount":2},{"id":18,"text":"A network administrator enabled antivirus and selected an SSL inspection profile on a firewall policy. When downloading an EICAR test file through HTTP, FortiGate detects the virus and blocks the file. When downloading the same file through HTTPS, FortiGate does not detect the virus and does not block the file, allowing it to be downloaded. The administrator confirms that the traffic matches the configured firewall policy. What are two reasons for the failed virus detection by FortiGate? (Choose two answers)","options":{"A":"The selected SSL inspection profile has certificate inspection enabled.","B":"The website is exempted from SSL inspection.","C":"The EICAR test file exceeds the protocol options oversize limit.","D":"The browser does not trust the FortiGate self-signed CA certificate."},"answer":["A","B"],"note":"","image":null,"correctCount":2},{"id":19,"text":"You have configured the below commands on a FortiGate.\n\nconfig system settings\nset strict-src-check enable\nend\n\nconfig system interface\nedit port1\nset src-check disable\nnext\nend\n\nWhat would be the impact of this configuration on FortiGate? (Choose one answer)","options":{"A":"FortiGate will enable strict RPF on all its interfaces and port1 will be enable for asymmetric routing.","B":"FortiGate will enable strict RPF on all its interfaces and port1 will be exempted from RPF checks.","C":"Port1 will be enabled with flexible RPF, and all other interfaces will be enabled for strict RPF.","D":"The global configuration will take precedence and FortiGate will enable strict RPF on all interfaces."},"answer":["B"],"note":"","image":null,"correctCount":1},{"id":20,"text":"Refer to the exhibit. What would be the impact of these settings on the Server certificate SNI check configuration on FortiGate? (Choose one answer)","options":{"A":"FortiGate will accept and use the CN in the server certificate for URL filtering if the SNI does not match the CN or SAN fields.","B":"FortiGate will accept the connection with a warning if the SNI does not match the CN or SAN fields.","C":"FortiGate will close the connection if the SNI does not match the CN or SAN fields.","D":"FortiGate will close the connection if the SNI does not match the CN and SAN fields."},"answer":["C"],"note":"","image":"assets-fortios-q020.jpg","correctCount":1},{"id":21,"text":"A new administrator is configuring FSSO authentication on FortiGate using DC Agent Mode. Which step is NOT part of the expected process? (Choose one answer)","options":{"A":"The DC agent sends login event data directly to FortiGate.","B":"The user logs into the windows domain.","C":"The collector agent forwards login event data to FortiGate.","D":"FortiGate determines user identity based on the IP address in the FSSO list."},"answer":["A"],"note":"","image":null,"correctCount":1},{"id":22,"text":"A network administrator is reviewing firewall policies in both Interface Pair View and By Sequence View. The policies appear in a different order in each view. Why is the policy order different in these two views? (Choose one answer)","options":{"A":"Policies in Interface Pair View are prioritized by security levels, while By Sequence View strictly follows the administrator's manual ordering.","B":"By Sequence View groups policies based on rule priority, while Interface Pair View always follows the order of traffic logs.","C":"The firewall dynamically reorders policies in Interface Pair View based on recent traffic patterns, but By Sequence View remains static.","D":"Interface Pair View sorts policies based on matching interfaces, while By Sequence View shows the actual processing order of rules."},"answer":["D"],"note":"","image":null,"correctCount":1},{"id":23,"text":"Refer to the exhibit. An administrator has created a new firewall address to use as the destination for a static route. Why is the administrator not able to select the new address in the Destination field of the new static route? (Choose one answer)","options":{"A":"In the new static route, the administrator must select Named Address.","B":"In the new firewall address, the FQDN address must first be resolved.","C":"In the new static route, the administrator must first set the interface to port2.","D":"In the new firewall address, Routing configuration must be enabled."},"answer":["D"],"note":"","image":"assets-fortios-q023.jpg","correctCount":1},{"id":24,"text":"FortiGate is operating in NAT mode and has two physical interfaces connected to the LAN and DMZ networks respectively. Which two statements about the requirements of connected physical interfaces on FortiGate are true? (Choose two answers)","options":{"A":"Both interfaces must have the interface role assigned.","B":"Both interfaces must have directly connected routes on the routing table.","C":"Both interfaces must have DHCP enabled and interfaces set to LAN and DMZ roles assigned.","D":"Both interfaces must have IP addresses assigned."},"answer":["B","D"],"note":"","image":null,"correctCount":2},{"id":25,"text":"When configuring a FortiGate in a multi-WAN setup, why would an administrator enable session preservation on an interface? (Choose one answer)","options":{"A":"To allow the FortiGate to dynamically change interfaces for all active sessions when a WAN link fails","B":"To make sure all sessions without source NAT enabled always use the primary WAN link","C":"To improve security by forcing users to authenticate again when the WAN link changes","D":"To ensure that existing SSL VPN connections remain on the same interface even if route changes occur"},"answer":["D"],"note":"","image":null,"correctCount":1},{"id":26,"text":"Refer to the exhibit. FortiGate has two separate firewall policies for Sales and Engineering to access the same web server with the same security profiles. Which action must the administrator perform to consolidate the two policies into one? (Choose one answer)","options":{"A":"Create an Aggregate interface that includes port1 and port2 to create a single firewall policy.","B":"Select port1 and port2 subnets in a single firewall policy.","C":"Replace port1 and port2 with the any interface in a single firewall policy.","D":"Enable Multiple Interface Policies to select port1 and port2 in the same firewall policy."},"answer":["D"],"note":"","image":"assets-fortios-q026.jpg","correctCount":1},{"id":27,"text":"You have configured an application control profile, set peer-to-peer traffic to Block under the Categories tab, and applied it to the firewall policy. However, your peer-to-peer traffic on known ports is passing through the FortiGate without being blocked. What FortiGate settings should you check to resolve this issue? (Choose one answer)","options":{"A":"FortiGuard category ratings","B":"Application and Filter Overrides","C":"Network Protocol Enforcement","D":"Replacement Messages for UDP-based Applications"},"answer":["C"],"note":"","image":null,"correctCount":1},{"id":28,"text":"When configuring firewall policies which of the following is true regarding the policy ID? (Choose two answers)","options":{"A":"It is mandatory to provide a policy ID while creating a firewall policy regardless of GUI or CLI.","B":"A firewall policy ID identifies the order of policy execution in firewall policies.","C":"You can create a policy in CLI with policy ID 0.","D":"A policy ID cannot be edited once a policy is created."},"answer":["C","D"],"note":"","image":null,"correctCount":2},{"id":29,"text":"Which two statements are correct when FortiGate enters conserve mode? (Choose two answers)","options":{"A":"FortiGate continues to run critical security actions, such as quarantine.","B":"FortiGate refuses to accept configuration changes.","C":"FortiGate halts complete system operation and requires a reboot to regain available resources.","D":"FortiGate continues to transmit packets without IPS inspection when the fail-open global setting in IPS is enabled."},"answer":["B","D"],"note":"","image":null,"correctCount":2},{"id":30,"text":"An administrator suspects that the Collector Agent is not forwarding login events to FortiGate. What is the most effective troubleshooting step? (Choose one answer)","options":{"A":"Verify if DC agent is enabled on the FortiGate","B":"Restart the domain controller to refresh authentication services.","C":"Verify if FortiGate is set to use LDAP authentication instead of FSSO.","D":"Check if TCP port 8000 is open between the collector agent and FortiGate."},"answer":["D"],"note":"","image":null,"correctCount":1},{"id":31,"text":"Refer to the exhibit. A network administrator is troubleshooting an IPsec tunnel between two FortiGate devices. The administrator has determined that phase 1 status is up, but phase 2 fails to come up. Based on the phase 2 configuration shown in the exhibit, which two configuration changes will bring phase 2 up? (Choose two answers)","options":{"A":"On BR1-FGT, set Seconds to 43200.","B":"On HQ-NGFW, enable Diffie-Hellman Group 2.","C":"On BR1-FGT, set Remote Address to 10.0.11.0/255.255.255.0.","D":"On HQ-NGFW, set Encryption to AES256."},"answer":["C","D"],"note":"","image":"assets-fortios-q031.jpg","correctCount":2},{"id":32,"text":"Refer to the exhibits. The exhibits show a diagram of a FortiGate device connected to the network, as well as the firewall policy and IP pool configuration on the FortiGate device. Two PCs, PC1 and PC2, are connected behind FortiGate and can access the internet successfully. However, when the administrator adds a third PC to the network (PC3), the PC cannot connect to the internet. Based on the information shown in the exhibit, which two configuration options can the administrator use to fix the connectivity issue for PC3? (Choose two answers)","options":{"A":"In the system settings, set Multiple Interface Policies to enable.","B":"In the IP pool configuration, set endip to 100.65.0.112.","C":"In the firewall policy, set match-vip to enable using CLI.","D":"In the IP pool configuration, set type to overload."},"answer":["B","D"],"note":"","image":"assets-fortios-q032.jpg","correctCount":2},{"id":33,"text":"Refer to the exhibits. An administrator has observed the performance status outputs on an HA cluster for 55 seconds. Which FortiGate is the primary? (Choose one answer)","options":{"A":"HQ-NGFW-2 with the parameter memory-failover-threshold setting","B":"HQ-NGFW-2 with the parameter priority setting","C":"HQ-NGFW-1 with the parameter memory-failover-flip-timeout setting","D":"HQ-NGFW-1 with the parameter override setting"},"answer":["A"],"note":"","image":"assets-fortios-q033.jpg","correctCount":1},{"id":34,"text":"Which statement correctly describes NetAPI polling mode for the FSSO collector agent? (Choose one answer)","options":{"A":"The collector agent uses a Windows API to query DCs for user logins.","B":"NetAPI polling can increase bandwidth usage in large networks.","C":"The NetSessionEnum function is used to track user logouts.","D":"The collector agent must search Windows application event logs."},"answer":["C"],"note":"","image":null,"correctCount":1},{"id":35,"text":"You have configured the FortiGate device for FSSO. A user is successful in log-in to Windows, but their access to the internet is denied. What should the administrator check first? (Choose one answer)","options":{"A":"Whether the user is assigned to the correct AD group.","B":"The FortiGate firewall policy settings for SSL decryption.","C":"The FortiGate FSSO active users list for user's IP address.","D":"The Windows event viewer for failed login attempts."},"answer":["C"],"note":"","image":null,"correctCount":1},{"id":36,"text":"What are three key routing principles in SD-WAN? (Choose three answers)","options":{"A":"By default, SD-WAN rules are skipped if the included SD-WAN members do not have a valid route to the destination.","B":"SD-WAN rules have precedence over any other type of routes.","C":"Regular policy routes have precedence over SD-WAN rules.","D":"By default, SD-WAN rules are skipped if only one route to the destination is available.","E":"By default, SD-WAN rules are skipped if the best route to the destination is not an SD-WAN member."},"answer":["A","C","E"],"note":"","image":null,"correctCount":3},{"id":37,"text":"Refer to the exhibits. An administrator configured the Web Filter Profile to block access to all social networking sites except Facebook. However, when users try to access facebook.com, they are redirected to a FortiGuard web filtering block page. Based on the exhibits, which configuration change must the administrator make to allow Facebook while blocking all other social networking sites? (Choose one answer)","options":{"A":"Change the Feature set of Web Filter Profile as Proxy-based.","B":"Change the type as Simple in the Static URL Filter section.","C":"Set the Action as Exempt for www.facebook.com in the Static URL Filter.","D":"Set the Social Networking action as warning in the FortiGuard Category Based Filter."},"answer":["C"],"note":"","image":"assets-fortios-q037.jpg","correctCount":1},{"id":38,"text":"Refer to the exhibit. You are asked to implement an antivirus profile for files downloaded through FTP, HTTP, and HTTPS. While testing, you are successful with HTTP and FTP protocols, but FortiGate does not block the file download over HTTPS. What could be the cause? (Choose one answer)","options":{"A":"Web filter is not enabled on the firewall policy to complement the antivirus profile.","B":"The feature set in the antivirus profile is not set to Flow-based.","C":"The SSL inspection mode in the firewall policy is not deep content inspection.","D":"The action on the firewall policy is not set to deny."},"answer":["C"],"note":"","image":"assets-fortios-q038.jpg","correctCount":1},{"id":39,"text":"Refer to the exhibits. The exhibits show a diagram of a FortiGate device connected to the network, as well as the IP pool configuration and firewall policy objects. The WAN (port2) interface has the IP address 100.65.0.101/24. The LAN (port4) interface has the IP address 10.0.11.254/24. Which IP address will be used to source NAT (SNAT) the traffic, if the user on HQ-PC-1 (10.0.11.50) pings the IP address of BR-FGT (100.65.1.111)? (Choose one answer)","options":{"A":"100.65.0.101","B":"100.65.0.49","C":"100.65.0.99","D":"100.65.0.149"},"answer":["C"],"note":"","image":"assets-fortios-q039.jpg","correctCount":1},{"id":40,"text":"Refer to the exhibits. The exhibits show a diagram of a FortiGate device connected to the network, and the firewall configuration. An administrator created a Deny policy with default settings to deny Webserver access for Remote-User2. The policy should work such that Remote-User1 must be able to access the Webserver while preventing Remote-User2 from accessing the Webserver. Which additional configuration can the administrator add to a deny firewall policy, beyond the default behavior, to block Remote-User2 from accessing the Webserver? (Choose one answer)","options":{"A":"Disable match-vip in the Allow_access policy.","B":"Configure a One-to-One IP Pool object in a new policy.","C":"Set the Destination address as Webserver in the Deny policy.","D":"Set the Destination address as Deny_IP in the Allow_access policy."},"answer":["C"],"note":"","image":"assets-fortios-q040.jpg","correctCount":1},{"id":41,"text":"Refer to the exhibits. The exhibits show the system performance output and default configuration of high memory usage thresholds on a FortiGate device. Based on the system performance output, what are the two possible outcomes? (Choose two answers)","options":{"A":"FortiGate has entered conserve mode.","B":"Administrators can access FortiGate only through the console port.","C":"Administrators can change the configuration.","D":"FortiGate drops new sessions."},"answer":["A","D"],"note":"","image":"assets-fortios-q041.jpg","correctCount":2},{"id":42,"text":"Refer to the exhibits. What would be the expected outcome in the HA cluster? (Choose one answer)","options":{"A":"HQ-NGFW-1 will synchronize the override disable setting with HQ-NGFW-2.","B":"HQ-NGFW-2 will take over as the primary because it has the override enable setting and higher priority than HQ-NGFW-1.","C":"HQ-NGFW-1 will remain the primary because HQ-NGFW-2 has lower priority.","D":"The HA cluster will become out of sync because the override setting must match on all HA members."},"answer":["B"],"note":"","image":"assets-fortios-q042.jpg","correctCount":1},{"id":43,"text":"Refer to the exhibits. An administrator wants to add HQ-ISFW-2 in the Security Fabric. HQ-ISFW-2 is in the same subnet as HQ-ISFW. After configuring the Security Fabric settings on HQ-ISFW-2, the status stays Pending. What can be the two possible reasons? (Choose two answers)","options":{"A":"Upstream FortiGate IP must be set to 10.0.11.254.","B":"SAML Single Sign-On must be set to Manual.","C":"HQ-ISFW-2 must be authorized on HQ-ISFW.","D":"Management IP must be set to 10.0.13.254."},"answer":["A","C"],"note":"","image":"assets-fortios-q043.jpg","correctCount":2},{"id":44,"text":"Refer to the exhibit. The exhibit shows the FortiGuard Category Based Filter section of a corporate web filter profile. An administrator must block access to download.com, which belongs to the Freeware and Software Downloads category. The administrator must also allow other websites in the same category. What are two solutions for satisfying the requirement? (Choose two answers)","options":{"A":"Configure a static URL filter entry for download.com with Type and Action set to Wildcard and Block, respectively.","B":"Configure a web override rating for download.com and select Malicious Websites as the subcategory.","C":"Configure a separate firewall policy with action Deny and an FQDN address object for *.download.com as destination address.","D":"Set the Freeware and Software Downloads category Action to Warning."},"answer":["A","B"],"note":"","image":"assets-fortios-q044.jpg","correctCount":2},{"id":45,"text":"You are encountering connectivity problems caused by intermediate devices blocking IPsec traffic. In which two ways can you effectively resolve the problem? (Choose two answers)","options":{"A":"You can use SSL VPN tunnel mode to prevent problems with blocked ESP and UDP ports (500 or 4500).","B":"You can turn on fragmentation to fix large certificate negotiation problems.","C":"You can configure a hub-and-spoke topology with SSL VPN tunnels to bypass blocked UDP ports.","D":"You should use the protocol IKEv2."},"answer":["A","B"],"note":"","image":null,"correctCount":2},{"id":46,"text":"You have implemented the application sensor and the corresponding firewall policy as shown in the exhibits. You cannot access any of the Google applications, but you are able to access www.fortinet.com. Which two actions would you take to resolve the issue? (Choose two answers)","options":{"A":"Add *Google*.com to the URL category in the security profile.","B":"Change the Inspection mode to Flow-based.","C":"Set the action for Google in the Application and Filter Overrides section to Allow.","D":"Move up Google in the Application and Filter Overrides section to set its priority to 1.","E":"Set SSL inspection to deep-content inspection."},"answer":["D","E"],"note":"Ключ перевірено за логікою Application Control/SSL inspection FortiOS 7.6: Google override має бути вище Excessive-Bandwidth; для HTTPS потрібна deep inspection.","image":"assets-fortios-q046.jpg","correctCount":2},{"id":47,"text":"Refer to the exhibits. You have implemented the application sensor and the corresponding firewall policy as shown in the exhibits. Which two factors can you observe from these configurations? (Choose two answers)","options":{"A":"YouTube search is allowed based on the Google Application and Filter override settings.","B":"Facebook access is allowed but you cannot play Facebook videos based on Video/Audio category filter settings.","C":"Facebook access is blocked based on the category filter settings.","D":"YouTube access is blocked based on Excessive-Bandwidth Application and Filter override settings."},"answer":["A","C"],"note":"","image":"assets-fortios-q047.jpg","correctCount":2},{"id":48,"text":"Refer to the exhibit, which contains a RADIUS server configuration. An administrator added a configuration for a new RADIUS server. While configuring, the administrator enabled Include in every user group. What is the impact of enabling Include in every user group in a RADIUS configuration? (Choose one answer)","options":{"A":"This option places the RADIUS server, and all users who can authenticate against that server, into every FortiGate user group.","B":"This option places the RADIUS server, and all users who can authenticate against that server, into every RADIUS group.","C":"This option places all users into every RADIUS user group, including groups that are used for the LDAP server on FortiGate.","D":"This option places all FortiGate users and groups required to authenticate into the RADIUS server, which, in this case, is FortiAuthenticator."},"answer":["A"],"note":"","image":"assets-fortios-q048.jpg","correctCount":1},{"id":49,"text":"Refer to the exhibits. An administrator creates a new address object on the root FortiGate (HQ-NGFW-1) in the Security Fabric. After synchronization, this object is not available on the downstream FortiGate (HQ-ISFW). What must the administrator do to synchronize the address object? (Choose one answer)","options":{"A":"Change the csf setting on HQ-ISFW (downstream) to set configuration-sync local.","B":"Change the csf setting on HQ-ISFW (downstream) to set saml-configuration-sync default.","C":"Change the csf setting on HQ-NGFW-1 (root) to set fabric-object-unification default.","D":"Change the csf setting on both devices to set downstream-access enable."},"answer":["C"],"note":"","image":"assets-fortios-q049.jpg","correctCount":1},{"id":50,"text":"Which three strategies are valid SD-WAN rule strategies for member selection? (Choose three answers)","options":{"A":"Lowest Cost (SLA) without load balancing","B":"Manual with load balancing","C":"Lowest Quality (SLA) with load balancing","D":"Lowest Cost (SLA) with load balancing","E":"Best Quality with load balancing"},"answer":["A","B","D"],"note":"","image":null,"correctCount":3},{"id":51,"text":"What are two characteristics of HA cluster heartbeat IP addresses in a FortiGate device? (Choose two answers)","options":{"A":"Heartbeat interfaces have virtual IP addresses that are manually assigned.","B":"Heartbeat IP addresses are used to distinguish between cluster members.","C":"The heartbeat interface of the primary device in the cluster is always assigned IP address 169.254.0.1.","D":"A change in the heartbeat IP address happens when a FortiGate device joins or leaves the cluster."},"answer":["B","D"],"note":"","image":null,"correctCount":2},{"id":52,"text":"Refer to the exhibit showing a debug flow output. Which two conclusions can you make from the debug flow output? (Choose two answers)","options":{"A":"The default gateway is configured on port2.","B":"The RPF check fails.","C":"The debug flow is for UDP traffic.","D":"The matching firewall policy denies the traffic."},"answer":["A","D"],"note":"","image":"assets-fortios-q052.jpg","correctCount":2},{"id":53,"text":"When FortiGate performs SSL/SSH full inspection, you can decide how it should react when it detects an invalid certificate. Which three actions are valid actions that FortiGate can perform when it detects an invalid certificate? (Choose three answers)","options":{"A":"Allow","B":"Trust & Allow","C":"Allow & Warning","D":"Block","E":"Block & Warning"},"answer":["A","B","D"],"note":"Варіант D відновлено з оригінального джерела: Block.","image":null,"correctCount":3},{"id":54,"text":"Refer to the exhibit, which shows a firewall policy to enable active authentication. When attempting to access an external website using an active authentication method, the user is not presented with a login prompt. What is the most likely reason for this situation? (Choose one answer)","options":{"A":"The Service DNS is required in the firewall policy.","B":"The Remote-users group must be set up correctly in the FSSO configuration.","C":"No matching user account exists for this user.","D":"The Remote-users group is not added to the Destination."},"answer":["A"],"note":"","image":"assets-fortios-q054.jpg","correctCount":1},{"id":55,"text":"Refer to the exhibit. Why did the FortiGate device drop the packet? (Choose one answer)","options":{"A":"It matched the default implicit firewall policy.","B":"It matched an explicitly configured firewall policy with the action DENY.","C":"It cannot reach the next-hop IP.","D":"It failed the RPF check."},"answer":["A"],"note":"","image":"assets-fortios-q055.jpg","correctCount":1},{"id":56,"text":"Refer to the exhibit, which shows a routing table. An administrator wants to create a new static route so the traffic to the subnet 172.20.1.0/24 is routed through port2 only. What are the two criteria that the administrator can use to achieve this objective? (Choose two answers)","options":{"A":"The new static route must have the distance set to 9.","B":"The existing static route through port3 must have the distance set to 11.","C":"The new static route must have the priority set to 3.","D":"The new static route must have the metric set to 1."},"answer":["A","B"],"note":"","image":"assets-fortios-q056.jpg","correctCount":2},{"id":57,"text":"Refer to the exhibit. Why is the Antivirus scan switch grayed out when you are creating a new antivirus profile for FTP? (Choose one answer)","options":{"A":"None of the inspected protocols are active in this profile.","B":"FortiGate, with less than 2 GB RAM, does not support the Antivirus scan feature.","C":"Antivirus scan is disabled under System -> Feature visibility.","D":"The Feature Set for the profile is Flow-based but it must be Proxy-based."},"answer":["A"],"note":"","image":"assets-fortios-q057.jpg","correctCount":1},{"id":58,"text":"An administrator has configured a dialup IPsec VPN on FortiGate with add-route enabled. However, the static route is not showing in the routing table. Which two statements about this scenario are correct? (Choose two answers)","options":{"A":"The administrator must enable a dynamic routing protocol on the dialup interface.","B":"The administrator must use a policy route instead of a static route for add-route to work properly.","C":"The administrator must ensure phase 2 is successfully established.","D":"The administrator must define the remote network correctly in the phase 2 selectors."},"answer":["C","D"],"note":"","image":null,"correctCount":2},{"id":59,"text":"An administrator configured a FortiGate device to act as a collector for agentless polling mode. What must the administrator add to the FortiGate device to retrieve AD user group information? (Choose one answer)","options":{"A":"TACACS server","B":"LDAP server","C":"RADIUS server","D":"Keycloak server"},"answer":["B"],"note":"У кадрі рядок Correct Answer не зчитався, але для agentless polling для отримання AD group information потрібен LDAP server → B.","image":null,"correctCount":1},{"id":60,"text":"What are two features of FortiGate FSSO agentless polling mode? (Choose two answers)","options":{"A":"FortiGate directs the collector agent to use a remote LDAP server.","B":"FortiGate uses the SMB protocol to read the event viewer logs from the DCs.","C":"FortiGate does not support workstation check.","D":"FortiGate uses the AD server as the collector agent."},"answer":["B","C"],"note":"","image":null,"correctCount":2},{"id":61,"text":"A network administrator has enabled full SSL inspection and web filtering on FortiGate. When visiting any HTTPS websites, the browser reports certificate warning errors. When visiting HTTP websites, the browser does not report errors. What is the reason for the certificate warning errors? (Choose one answer)","options":{"A":"The matching firewall policy is set to proxy inspection mode.","B":"The certificate used by FortiGate for SSL inspection does not contain the required certificate extensions.","C":"The full SSL inspection feature does not have a valid license.","D":"The browser does not trust the certificate used by FortiGate for SSL inspection."},"answer":["D"],"note":"","image":null,"correctCount":1},{"id":62,"text":"A network administrator wants to set up redundant IPsec VPN tunnels on FortiGate by using two IPsec VPN tunnels and static routes. All traffic must be routed through the primary tunnel when both tunnels are up. The secondary tunnel must be used only if the primary tunnel goes down. In addition, FortiGate should be able to detect a dead tunnel to speed up tunnel failover. Which two key configuration changes must the administrator make on FortiGate to meet the requirements? (Choose two answers)","options":{"A":"In the phase1-interface, enable npu-offload to detect a dead tunnel.","B":"Configure a lower distance on the static route for the primary tunnel, and a higher distance on the static route for the secondary tunnel.","C":"Enable Dead Peer Detection.","D":"Use the VPN wizard to create an IPsec template for a redundant IPsec VPN tunnel."},"answer":["B","C"],"note":"","image":null,"correctCount":2},{"id":63,"text":"An administrator wants to form an HA cluster using the FGCP protocol. Which two requirements must the administrator ensure both members fulfill? (Choose two answers)","options":{"A":"They must have the same HA group ID.","B":"They must have the heartbeat interfaces in the same subnet.","C":"They must have the same number of configured VDOMs.","D":"They must have the same hard drive configuration."},"answer":["A","D"],"note":"","image":null,"correctCount":2},{"id":64,"text":"FortiGate is integrated with FortiAnalyzer and FortiManager. When creating a firewall policy, which attribute must an administrator include to enhance functionality and enable log recording on FortiAnalyzer and FortiManager? (Choose one answer)","options":{"A":"Policy ID","B":"LogID","C":"Universally Unique Identifier","D":"Sequence ID"},"answer":["C"],"note":"","image":null,"correctCount":1},{"id":65,"text":"Refer to the exhibit. The administrator configured SD-WAN rules and set the FortiGate traffic log page to display SD-WAN-specific columns: SD-WAN Quality and SD-WAN Rule Name. FortiGate allows the traffic according to policy ID 1 placed at the top. This is the policy that allows SD-WAN traffic. Despite these settings, the traffic logs do not show the name of the SD-WAN rule used to steer those traffic flows. What could be the reason? (Choose one answer)","options":{"A":"SD-WAN rule names do not appear immediately. The administrator must refresh the page.","B":"There is no application control profile applied to the firewall policy.","C":"FortiGate load balanced the traffic according to the implicit SD-WAN rule.","D":"Destinations in the SD-WAN rules are configured for each application, but feature visibility is not enabled."},"answer":["C"],"note":"","image":"assets-fortios-q065.jpg","correctCount":1},{"id":66,"text":"An administrator manages a FortiGate model that supports NTurbo. How does NTurbo acceleration enhance antivirus performance? (Choose one answer)","options":{"A":"For proxy-based inspection, NTurbo offloads traffic to the content processor.","B":"For flow-based inspection, NTurbo establishes a dedicated data path to redirect traffic between the IPS engine and FortiGate ingress and egress","C":"For proxy-based inspection, NTurbo buffers the whole file and then sends it to the antivirus engine.","D":"For flow-based inspection, NTurbo creates two inspection sessions on the FortiGate device."},"answer":["B"],"note":"","image":null,"correctCount":1},{"id":67,"text":"Refer to the exhibit. Review the intrusion prevention system (IPS) profile signature settings shown in the exhibit. What can you conclude about the signature when adding the FTP.Login.Failed signature to the IPS Sensor profile? (Choose one answer)","options":{"A":"The signature setting includes a group of other signatures.","B":"FortiGate stores a local copy of the packet that matches the signature.","C":"FortiGate allows this low-severity signature packet and creates a log.","D":"The signature setting uses a custom rating threshold."},"answer":["B"],"note":"","image":"assets-fortios-q067.jpg","correctCount":1},{"id":68,"text":"Refer to the exhibits. A diagram of a FortiGate device connected to the network, VIP object, and firewall policy configurations are shown. The WAN (port2) interface has the IP address 100.65.0.101/24. The LAN (port4) interface has the IP address 10.0.11.254/24. If the host 100.65.1.111 sends a TCP SYN packet on port 443 to 100.65.0.200, what will the source address, destination address, and destination port of the packet be at the time FortiGate forwards the packet to the destination? (Choose one answer)","options":{"A":"10.0.11.254, 10.0.15.50, and 4443, respectively","B":"100.65.1.111, 10.0.11.50, and 443, respectively","C":"10.0.11.254, 100.65.0.200, and 443, respectively","D":"100.65.1.111, 10.0.11.50, and 4443, respectively"},"answer":["D"],"note":"","image":"assets-fortios-q068.jpg","correctCount":1},{"id":69,"text":"Refer to the exhibits. The exhibits show a diagram of a FortiGate device connected to the network, and the firewall policies, VIP, and IP pool configurations on the FortiGate device. The WAN (port2) interface has the IP address 100.65.0.101/24. The LAN (port4) interface has the IP address 10.0.11.254/24. The first firewall policy has NAT enabled using the IP pool. The second firewall policy is configured with a VIP as the destination address. Which IP address will be used to source NAT (SNAT) the internet traffic coming from a workstation with the IP address 10.0.11.50? (Choose one answer)","options":{"A":"100.65.0.101","B":"100.65.0.200","C":"100.65.0.102","D":"10.0.11.254"},"answer":["C"],"note":"","image":"assets-fortios-q069.jpg","correctCount":1},{"id":70,"text":"Based on the routing table shown in the exhibit, which two statements are true? (Choose two answers)","options":{"A":"A packet with the source IP address 10.100.110.10 arriving on port3 is allowed if strict RPF is disabled.","B":"A packet with the source IP address 10.100.110.10 arriving on port2 is allowed if strict RPF is enabled.","C":"A packet with the source IP address 10.0.13.10 arriving on port2 is allowed if strict RPF is disabled.","D":"A packet with the source IP address 10.10.10.10 arriving on port2 is allowed if strict RPF is enabled."},"answer":["B","C"],"note":"","image":"assets-fortios-q070.jpg","correctCount":2},{"id":71,"text":"An administrator configures FortiGuard servers as DNS servers on FortiGate using default settings. What is true about the DNS connection to a FortiGuard server? (Choose one answer)","options":{"A":"It uses DNS over TLS.","B":"It uses DNS over HTTPS.","C":"It uses UDP 8888.","D":"It uses UDP 53."},"answer":["A"],"note":"","image":null,"correctCount":1},{"id":72,"text":"What are two features of collector agent advanced mode? (Choose two answers)","options":{"A":"dvanced mode supports nested or inherited groups.","B":"In advanced mode, security profiles can be applied only to user groups, not individual users.","C":"In advanced mode, FortiGate can be configured as an LDAP client and group filters can be configured on FortiGate.","D":"Advanced mode uses the Windows convention—NetBios: Domain\\Username."},"answer":["A","C"],"note":"","image":null,"correctCount":2},{"id":73,"text":"Refer to the exhibits. Both HA members were configured at the same time. After one week, an administrator wants to force an HA failover. Which action can the administrator take? (Choose one answer)","options":{"A":"Reset HA uptime on HQ-NGFW-1.","B":"Set override enable on HQ-NGFW-2.","C":"Increase HA priority on HQ-NGFW-2.","D":"Set the monitored port1 down on HQ-NGFW-1."},"answer":["A"],"note":"У Brave Dumps показано D, але Fortinet 7.6 прямо вказує diagnose sys ha reset-uptime як спосіб вручну скинути HA uptime і тестувати failover. Для тренажера використано A.","image":"assets-fortios-q073.jpg","correctCount":1},{"id":74,"text":"Refer to the exhibit. What can you conclude from the log shown in the exhibit? (Choose one answer)","options":{"A":"The IPS scan is paused by the IPS diagnostic command with bypass mode option 5.","B":"The IPS socket buffer is full and IPS engine needs more memory to create new sessions.","C":"The IPS session scan is paused and reevaluating the packet because of a dirty flag.","D":"The IPS socket buffer is full and IPS engine cannot decode a packet."},"answer":["B"],"note":"","image":"assets-fortios-q074.jpg","correctCount":1},{"id":75,"text":"Refer to the exhibits. You have implemented the application sensor and the corresponding firewall policy as shown in the exhibits. You cannot access any of the Google applications, but you are able to access www.fortinet.com. What would you do to resolve this issue? (Choose one answer)","options":{"A":"Change the Inspection mode to Proxy-based.","B":"Set SSL inspection to deep-content-inspection.","C":"Move up Google in the Application and Filter Overrides section to set its priority to 1.","D":"Add Google.com to the URL category in the security profile."},"answer":["C"],"note":"У Brave Dumps показано B. За конфігурацією Google override стоїть нижче блокуючого Excessive-Bandwidth filter; Fortinet описує послідовну оцінку override-ів. Для тренажера використано C.","image":"assets-fortios-q075.jpg","correctCount":1},{"id":76,"text":"Refer to the exhibits. A web filter profile configuration and firewall policy configuration are shown. You are trying to access www.facebook.com, but you are redirected to a FortiGuard web filtering block page. Based on the exhibits, what is the possible cause of the issue? (Choose one answer)","options":{"A":"The web filter profile feature set is configured incorrectly.","B":"The web rating override configuration is incorrect.","C":"The firewall policy inspection mode is incorrect.","D":"For www.facebook.com, the URL filter action is incorrect."},"answer":["B"],"note":"","image":"assets-fortios-q076.jpg","correctCount":1},{"id":77,"text":"Which two statements about the Security Fabric rating are true? (Choose two answers)","options":{"A":"A license is required to obtain an executive summary in the Security Rating section.","B":"The root FortiGate provides executive summaries of all the FortiGate devices in the Security Fabric.","C":"The Security Posture category provides PCI compliance results.","D":"Security Rating Insights are available only in the Security Rating page."},"answer":["B","C"],"note":"","image":null,"correctCount":2},{"id":78,"text":"An administrator has configured the following settings:\n\nconfig system settings\nset ses-denied-traffic enable\nend\n\nconfig system global\nset block-session-timer 30\nend\n\nWhat are the two results of this configuration? (Choose two answers)","options":{"A":"Denied users are blocked for 30 minutes.","B":"A session for denied traffic is created.","C":"Session helpers are disabled for denied traffic.","D":"The number of logs generated by denied traffic is reduced."},"answer":["B","D"],"note":"","image":null,"correctCount":2},{"id":79,"text":"Which two statements about the FortiGuard connection are true? (Choose two answers)","options":{"A":"FortiGate is using the default port for FortiGuard communication.","B":"FortiGate identified the FortiGuard Server using DNS lookup.","C":"The weight increases as the number of failed packets rises.","D":"You can configure unreliable protocols to communicate with FortiGuard Server."},"answer":["C","D"],"note":"Ключ C,D узгоджується з FortiGuard debug/rating поведінкою: weight росте з невдалими пакетами; при вимкненому anycast можна використовувати UDP.","image":"assets-fortios-q079.jpg","correctCount":2},{"id":80,"text":"Refer to the exhibits. The exhibits show the application sensor configuration and the Excessive-Bandwidth and Apple filter details. Based on the configuration, what will happen to Apple FaceTime if there are only a few calls originating or incoming? (Choose one answer)","options":{"A":"Apple FaceTime will be allowed, based on the Video/Audio category configuration.","B":"Apple FaceTime will be blocked, based on the Excessive-Bandwidth filter configuration.","C":"Apple FaceTime will be allowed, based on the Apple filter configuration.","D":"Apple FaceTime will be allowed only if the Apple filter in Application and Filter Overrides is set to Allow."},"answer":["B"],"note":"","image":"assets-fortios-q080.jpg","correctCount":1},{"id":81,"text":"How can the administrator view the log messages shown in the exhibit? (Choose two answers)","options":{"A":"Filtering by Policy UUID and Application Name in the log entry","B":"By right clicking the Implicit deny policy","C":"Through FortiGate CLI command diagnose log test","D":"Through Security event log page"},"answer":["A","D"],"note":"","image":"assets-fortios-q081.jpg","correctCount":2},{"id":82,"text":"An administrator wants to address shadow IT visibility challenges and prevent users from sending sensitive files outside the organization without proper approval. Which FortiSASE method should the administrator implement to achieve these goals? (Choose one answer)","options":{"A":"Secure SD-WAN access (SSD-WAN)","B":"Secure private access (SPA)","C":"Secure SaaS access (SSA)","D":"Secure internet access (SIA)"},"answer":["C"],"note":"","image":null,"correctCount":1},{"id":83,"text":"You are configuring FortiAnalyzer on FortiGate. Which step must you take to connect FortiAnalyzer to FortiGate? (Choose one answer)","options":{"A":"Verify the FortiAnalyzer serial number.","B":"Authorize FortiGate on FortiAnalyzer.","C":"Enable disk logging on FortiGate.","D":"Configure UDP port 514 on FortiGate"},"answer":["B"],"note":"","image":null,"correctCount":1},{"id":84,"text":"Refer to the exhibit. You deployed a FortiGate Cloud-Native Firewall (CNF) in AWS for FortiGate CNF policy enforcement for EC2 instance traffic. Which path does the EC2 traffic take from the EC2 instance to the internet? (Choose one answer)","options":{"A":"EC2 instance → internet gateway (IGW) → gateway load balancer (GWLB) → FortiGate CNF → internet","B":"EC2 instance → GWLB endpoint (GWLBe) → FortiGate CNF → IGW → internet","C":"EC2 instance → FortiGate CNF → GWLB → GWLBe → IGW → internet","D":"EC2 instance → GWLBe → FortiGate CNF → GWLBe → IGW → internet"},"answer":["D"],"note":"","image":"assets-fortios-q084.jpg","correctCount":1},{"id":85,"text":"You are onboarding an agentless, secure web gateway (SWG) endpoint for secure internet access (SIA). What will happen to the user's nonweb traffic? (Choose one answer)","options":{"A":"All the nonweb traffic will bypass FortiSASE.","B":"The endpoint will use split tunneling to redirect nonweb traffic to FortiSASE.","C":"FortiSASE will use Firewall-as-a-Service (FWaaS) to redirect nonweb traffic.","D":"FortiSASE will use SWG to redirect nonweb traffic to FortiExtender."},"answer":["A"],"note":"","image":null,"correctCount":1},{"id":86,"text":"Which two features of IPsec IKEv1 authentication are supported by FortiGate? (Choose two answers)","options":{"A":"Extended authentication (XAuth) to request the remote peer to provide a username and password","B":"No certificate is required on the remote peer when you set the certificate signature as the authentication method","C":"Extended authentication (XAuth) for faster authentication because fewer packets are exchanged","D":"Pre-shared key and certificate signature as authentication methods"},"answer":["A","D"],"note":"","image":null,"correctCount":2},{"id":87,"text":"How does FortiExtender connect to FortiSASE in a site-based, remote internet access method? (Choose one answer)","options":{"A":"FortiExtender uses the proxy auto-configuration (PAC) file and an explicit web proxy to connect.","B":"FortiExtender first connects to a FortiGate LAN extension through a secure web gateway (SWG).","C":"FortiExtender establishes a secure SSL connection using FortiClient.","D":"FortiExtender uses a Virtual Extensible LAN (VXLAN)-over-IPsec connection."},"answer":["D"],"note":"VXLAN-over-IPsec є штатним способом site-based Secure Edge/LAN extension до FortiSASE.","image":null,"correctCount":1},{"id":88,"text":"Refer to the exhibit. You deployed a FortiGate Cloud-Native Firewall (CNF) in AWS. During the deployment, which components must the FortiGate CNF create to handle traffic from the EC2 instance? (Choose one answer)","options":{"A":"The gateway load balancer endpoint (GWLBe) in the customer virtual private cloud (VPC)","B":"The GWLB, GWLBe, and the internet gateway (IGW) in the customer VPC","C":"The CNF VPC, customer VPC, and GWLB","D":"The customer VPC and GWLBe"},"answer":["A"],"note":"","image":"assets-fortios-q088.jpg","correctCount":1},{"id":89,"text":"Refer to the exhibit. Which two ways can you view the log messages shown in the exhibit? (Choose two answers)","options":{"A":"In the Forward Traffic section","B":"By right clicking the implicit deny policy","C":"Using the FortiGate CLI command diagnose log test","D":"By filtering by policy universally unique identifier (UUID) and application name in the log entry"},"answer":["A","D"],"note":"","image":"assets-fortios-q089.jpg","correctCount":2},{"id":90,"text":"Which two components are part of the secure internet access (SIA) agent-based mode on FortiSASE? (Choose two answers)","options":{"A":"VPN policies","B":"FortiSASE Firewall-as-a-Service (FWaaS)","C":"The proxy auto-configuration (PAC) file","D":"FortiExtender"},"answer":["A","B"],"note":"","image":null,"correctCount":2},{"id":91,"text":"There are multiple dialup IPsec VPNs configured in aggressive mode on the HQ FortiGate. The requirement is to connect dial-up users to their respective department VPN tunnels. Which phase 1 setting you can configure to match the user to the tunnel? (Choose one answer)","options":{"A":"Peer ID","B":"Local Gateway","C":"Dead Peer Detection","D":"IKE Mode Config"},"answer":["A"],"note":"","image":null,"correctCount":1},{"id":92,"text":"Which statement correctly describes Fortinet Security Intelligence Access (SIA)? (Choose one answer)","options":{"A":"It provides URL filtering based on static local categories only","B":"It uses FortiGuard threat intelligence to dynamically block malicious destinations","C":"It encrypts traffic between FortiGate and FortiAnalyzer","D":"It is used to authenticate users through FortiAuthenticator"},"answer":["B"],"note":"","image":null,"correctCount":1},{"id":93,"text":"What is the primary goal of Fortinet Secure Access Service Edge (SASE)? (Choose one answer)","options":{"A":"To replace on-premises firewalls with standalone cloud firewalls","B":"To provide secure connectivity and security services from the cloud for remote users","C":"To manage FortiGate devices using FortiManager","D":"To analyze logs and events using FortiAnalyzer"},"answer":["B"],"note":"","image":null,"correctCount":1},{"id":94,"text":"When configuring the connection between FortiGate and FortiAnalyzer, which option indicates that reliable traffic is enabled? (Choose one answer)","options":{"A":"The connection status shows a green check icon","B":"The interface status is set to up","C":"A padlock icon appears in the connection settings","D":"The logging mode is set to real-time"},"answer":["C"],"note":"Padlock у FortiAnalyzer connection settings означає reliable logging.","image":null,"correctCount":1},{"id":95,"text":"An administrator wants to form an HA cluster using the FGCP protocol. Both FortiGate devices are configured with the set override enable command. Arrange the criteria in the order in which the FGCP protocol uses them to elect the primary FortiGate.","options":{},"answer":["Connected monitored ports","Priority","HA uptime","FortiGate serial number"],"note":"","image":null,"correctCount":4},{"id":96,"text":"The FortiGate device HQ-NGFW-1 with the IP address 10.0.13.254 sends logs to the FortiAnalyzer device with the IP address 10.0.13.125. The administrator wants to verify that reliable logging is enabled on HQ-NGFW-1. Which exhibit helps with the verification? (Choose one answer)","options":{"A":"Image A","B":"Image B","C":"Image C","D":"Image D"},"answer":["D"],"note":"","image":"assets-fortios-q096.jpg","correctCount":1},{"id":97,"text":"Which three methods are used by the collector agent for AD polling? (Choose three answers)","options":{"A":"NetAPI","B":"WMI","C":"WinSecLog","D":"DNS reverse lookup","E":"FSSO REST API"},"answer":["A","B","C"],"note":"","image":null,"correctCount":3},{"id":98,"text":"A network administrator is configuring an IPsec VPN tunnel for a sales employee travelling abroad. Which IPsec Wizard template must the administrator apply? (Choose one answer)","options":{"A":"Site to Site","B":"Hub-and-Spoke","C":"Dial up User","D":"Remote Access"},"answer":["D"],"note":"IPsec Wizard template для travelling sales employee — Remote Access → D.","image":null,"correctCount":1},{"id":99,"text":"Refer to the exhibit to view the firewall policy. Why would the firewall policy not block a well-known virus, for example eicar? (Choose one answer)","options":{"A":"The action on the firewall policy is not set to DENY.","B":"Web filter is not enabled, so the firewall policy does not complement the antivirus profile.","C":"The firewall policy is not configured in proxy-based inspection mode.","D":"The firewall policy does not apply deep content inspection."},"answer":["D"],"note":"У відео ключ не відобразився OCR, але причина — certificate inspection не розшифровує HTTPS payload; потрібна deep inspection → D.","image":"assets-fortios-q099.jpg","correctCount":1},{"id":100,"text":"Refer to the exhibits. You have implemented the application sensor and the corresponding firewall policy as shown in the exhibits. You cannot access any of the Google applications, but you are able to access www.fortinet.com. What would you do to resolve this issue? (Choose one answer)","options":{"A":"Set the action for Excessive-Bandwidth in the Application and Filter Overrides section to Allow.","B":"Move up Google in the Application and Filter Overrides section to set its priority to 1.","C":"Add Google.com to the URL category in the security profile.","D":"Set the action for Google in the Application and Filter Overrides section to Monitor."},"answer":["D"],"note":"","image":"assets-fortios-q100.jpg","correctCount":1},{"id":101,"text":"Refer to the exhibit. A network administrator is troubleshooting an IPsec tunnel between two FortiGate devices. The administrator has determined that phase 1 failed to come up. The administrator has also re-entered the pre-shared key on both FortiGate devices to make sure they match. Based on the phase 1 configuration and the diagram shown in the exhibit, which two configuration changes can the administrator make to bring phase 1 up? (Choose two answers)","options":{"A":"On HQ-NGFW, set IKE mode to Main (ID protection).","B":"On both FortiGate devices set Dead Peer Detection to On Demand.","C":"On BR1-FGT, set port2 to Interface.","D":"On HQ-NGFW, disable Diffie-Hellman group 2."},"answer":["A","C"],"note":"У джерелі A,C. Схема залежить від конкретних Phase 1 параметрів у exhibit; залишено ключ джерела, але питання позначено для повторної ручної перевірки.","image":"assets-fortios-q101.jpg","correctCount":2},{"id":102,"text":"Refer to the exhibits. You have implemented the application sensor and the corresponding firewall policy as shown in the exhibits. You can access the Gmail chat application, but there is no log generated under security logs. Which two actions would you take to resolve the issue? (Choose two answers)","options":{"A":"Set SSL inspection to deep-inspection.","B":"Move up Google in the Application and Filter Overrides section to set its priority to 1.","C":"Add *Google*.com to the URL category in the security profile.","D":"Change the Inspection mode to Flow-based.","E":"Set the action for Gmail_Chat in the Application and Filter Overrides section to Monitor."},"answer":["A","E"],"note":"","image":"assets-fortios-q102.jpg","correctCount":2},{"id":103,"text":"An administrator wants to form an HA cluster using the FGCP protocol. Both FortiGate devices are configured with the set override disable command. Arrange the criteria in the order in which the FGCP protocol uses them to elect the primary FortiGate.","options":{},"answer":["Connected monitored ports","HA uptime","Priority","FortiGate serial number"],"note":"override disable: monitored ports → HA uptime → priority → serial number. System uptime не входить у чотири кроки.","image":null,"correctCount":4}]},{"id":"fortisiem-practice-76","vendor":"Fortinet","product":"FortiSIEM","title":"FortiSIEM Practice Exam","description":"76 questions reconstructed from the provided recording/source HTML.","questionCount":76,"imageCount":40,"source":"slate-practice_CORRECTED(1).html","questions":[{"id":1,"text":"What is the Group: VPN Gateway value a reference to? (Choose one answer)","options":{"A":"A configuration management database (CMDB) device group","B":"A FortiSIEM rule folder","C":"A FortiSIEM watchlist","D":"A FortiGate address group"},"answer":["A"],"note":"","image":"assets-fortisiem-q001-v2.png","correctCount":1},{"id":2,"text":"If the Capture Variable step ingests the source IP address from an incident and the Block Source IP on FGT step blocks that source IP address on the configured firewall, what will happen when this playbook is executed? (Choose one answer)","options":{"A":"Asingle source IP address from the incident will be blocked on the first playbook connector.","B":"The same source IP address will be blocked on all three firewalls.","C":"Three different source IP addresses, depending on the network configuration of the firewalls, will be blocked.","D":"A different source IP address, depending on the organization, will be blocked on all three firewalls."},"answer":["B"],"image":"assets-fortisiem-q002.jpg","correctCount":1},{"id":3,"text":"If you group these events by the Reporting Device, Reporting IP, and Application Category attributes, how may results will FortiSIEM display? (Choose one answer)","options":{"A":"Six","B":"Five","C":"Three","D":"Four"},"answer":["B"],"image":"assets-fortisiem-q003.jpg","correctCount":1},{"id":4,"text":"When selecting multiple rules at once on FortiSIEM, which actions can you perform? (Choose one answer)","options":{"A":"You can only change the severity of multiple rules at a time.","B":"You can change the severity, activate, or deactivate multiple rules at a time.","C":"You can view, edit, or activate only one rule at a time.","D":"You can only activate or deactivate multiple rules at a time."},"answer":["B"],"image":null,"correctCount":1},{"id":5,"text":"Which two settings must you configure to allow FortiSIEM to automatically apply tags to devices on FortiClient EMS? (Choose two answers)","options":{"A":"FortiSIEM API credentials defined on FortiClient EMS","B":"Zero trust network access (ZTNA) tags defined on FortiClient EMS","C":"Remediation scripts or playbooks","D":"FortiClient EMS API credentials defined on FortiSIEM"},"answer":["A","D"],"image":null,"correctCount":2},{"id":6,"text":"Which data collection method generates the most comprehensive information for FortiSIEM user entity and behavior analytics (UEBA) models? (Choose one answer)","options":{"A":"Linux log","B":"FortiSIEM Linux agent","C":"Windows Sysmon","D":"Windows UEBA agent"},"answer":["D"],"image":null,"correctCount":1},{"id":7,"text":"You want to reference the first source IP address from an incident in a playbook. Which option shows the correct Jinja syntax for using a variable for the source IP address in a FortiSIEM playbook? (Choose one answer)","options":{"A":"srcIpAddr.records[0]","B":"record(srcIpAddr)","C":"vars.input.records[0].srcIpAddr","D":"srcIpAddr(1)"},"answer":["C"],"image":null,"correctCount":1},{"id":8,"text":"The rule is not generating an incident, but the search parameters are matching events in the Analytics tab. What is wrong with the rule conditions? (Choose one answer)","options":{"A":"The Destination Host Name value is not fully qualified.","B":"The Group By attributes are too restrictive.","C":"The Aggregate attribute is too restrictive.","D":"The Event Type refers to a CMDB lookup, but it should refer to an event Lookup."},"answer":["B"],"image":"assets-fortisiem-q008.jpg","correctCount":1},{"id":9,"text":"The configuration for a machine learning (ML) dataset using anomaly detection is shown. If data for this model is generated every hour, how long must the FortiSIEM device be up before it can produce a valid training set? (Choose one answer)","options":{"A":"10 hours","B":"30 hours","C":"24 hours","D":"3 hours"},"answer":["A"],"image":"assets-fortisiem-q009.jpg","correctCount":1},{"id":10,"text":"When the subpattern is matched, what does the time condition of 60 seconds mean? (Choose one answer)","options":{"A":"The rule will trigger remediation actions every 60 seconds when the subpattern is triggered.","B":"It is the time period over which the rule will aggregate and evaluate events.","C":"The rule engine will evaluate events every 60 seconds looking for the subpattern.","D":"The subpattern must be matched at least twice within 60 seconds to trigger this rule."},"answer":["B"],"image":"assets-fortisiem-q010.jpg","correctCount":1},{"id":11,"text":"If a rule containing the automation policy shown in the exhibit is triggered, what will happen? (Choose one answer)","options":{"A":"Associated source IP addresses will be blocked on all FortiGate firewalls in the Banking organization.","B":"Associated source IP addresses will be blocked on all devices in the Banking organization.","C":"Associated source IP addresses will be blocked on all FortiGate firewalls.","D":"Associated source IP addresses will be blocked on two FortiGate firewalls."},"answer":["D"],"image":"assets-fortisiem-q011.jpg","correctCount":1},{"id":12,"text":"Which two ways can an automation service playbook be triggered? (Choose two answers)","options":{"A":"Manually, through an event in an analytics search","B":"Manually, through the incident details menu","C":"Automatically, when a dashboard threshold is reached","D":"Automatically, through an automation policy"},"answer":["B","D"],"image":null,"correctCount":2},{"id":13,"text":"Which running mode takes the most time to perform machine learning (ML) tasks? (Choose one answer)","options":{"A":"Regression","B":"Forecasting","C":"Local auto","D":"Clustering"},"answer":["C"],"image":null,"correctCount":1},{"id":14,"text":"How does FortiSIEM update the incident details if the same rule triggers repeatedly? (Choose one answer)","options":{"A":"FortiSIEM updates the Incident Count value and Last Seen timestamp.","B":"FortiSIEM changes the incident status to Repeated, and updates the Last Seen timestamp.","C":"FortiSIEM generates a new incident each time the rule triggers and updates all the First Seen and Last Seen timestamps.","D":"FortiSIEM generates a new incident based on the Rule Frequency value, and updates the First Seen and Last Seen timestamps."},"answer":["A"],"image":null,"correctCount":1},{"id":15,"text":"You want to build a query that includes only events that contain a username. What is a valid analytics query that will perform this type of search? (Choose one answer)","options":{"A":"User IS NOT NULL","B":"User CONTAIN","C":"User STARTS_WITH","D":"User IS VALID"},"answer":["A"],"image":null,"correctCount":1},{"id":16,"text":"Which three items are required to create an incident attribute to associate with an incident in a FortiSIEM rule? (Choose three answers)","options":{"A":"Operator","B":"Event attribute","C":"Event type","D":"Subpattern","E":"Filter attribute"},"answer":["B","D","E"],"image":null,"correctCount":3},{"id":17,"text":"You want to create a dashboard like the shown in the exhibit on your FortiSIEM device. Which item defines the data that these widgets display? (Choose one answer)","options":{"A":"FortiSIEM UEBA tags","B":"FortiSIEM reports","C":"FortiSIEM discovery rules","D":"FortiSIEM incidents"},"answer":["B"],"image":"assets-fortisiem-q017.jpg","correctCount":1},{"id":18,"text":"If a user account is Locked after five failed Login attempts, how many times will this rule be triggered if three individual users all fail their login 10 times? (Choose one answer)","options":{"A":"Three","B":"One","C":"Five","D":"Fifteen"},"answer":["A"],"image":"assets-fortisiem-q018.jpg","correctCount":1},{"id":19,"text":"A rule that detects network connections to an SSH server is triggering constantly in response to background internet traffic and must be tuned. Which method is used to tune this rule and solve the issue? (Choose one answer)","options":{"A":"Increase the time window on the FortiSIEM rule.","B":"Update the Group By attribute to include only allowed host IP addresses.","C":"Block connections from unauthorized networks before they reach the server.","D":"Increase the COUNT (Matched Events) value in the subpattern."},"answer":["D"],"image":null,"correctCount":1},{"id":20,"text":"Which two items can be referenced in the incident details when this rule is triggered and creates an incident? (Choose two answers)","options":{"A":"Domain Account Lockout","B":"Reporting Device","C":"User","D":"Event Type","E":"COUNT(Matched Events)"},"answer":["B","C"],"image":"assets-fortisiem-q020.jpg","correctCount":2},{"id":21,"text":"Which two lookup types can you reference as the subquery in a nested analytics query? (Choose two answers)","options":{"A":"Event query","B":"LDAP query","C":"CMDB query","D":"API query"},"answer":["A","C"],"image":"assets-fortisiem-q021.jpg","correctCount":2},{"id":22,"text":"You want to use a machine learning (ML) model to train data with the following characteristics shown in the exhibit. Which ML model is the best fit to match the data in the exhibit? (Choose one answer)","options":{"A":"Anomaly detection","B":"Elliptical envelope","C":"Clustering","D":"Forecasting"},"answer":["C"],"image":"assets-fortisiem-q022.jpg","correctCount":1},{"id":23,"text":"FortiSIEM is receiving syslog events from a firewall. You are trying to search raw event logs for traffic from the last two hours that contain the keyword \"UDP”. However, you are getting no results from the search. Based on the filter shown in the exhibit, why are you getting no search results? (Choose one answer)","options":{"A":"You can perform raw event log searches using only an Event Keyword search.","B":"The AND operator in the Next column is the wrong operator for this type of search.","C":"You are using udp in the Value field, but you must use UDP.","D":"The = operator in the Operator column is the wrong operator for this type of search."},"answer":["D"],"image":"assets-fortisiem-q023.jpg","correctCount":1},{"id":24,"text":"Why are some of the fields highlighted in red? (Choose one answer)","options":{"A":"The Event Receive Time attribute is a valid choice to sort by.","B":"No Raw Event Log attribute information is available.","C":"Multiple unique values cannot be grouped.","D":"The attribute COUNT(Matched Events) is an invalid expression."},"answer":["C"],"image":"assets-fortisiem-q024.jpg","correctCount":1},{"id":25,"text":"Which two categories can you map to the MITRE ATT&CK coverage tables on FortiSIEM? (Choose two answers)","options":{"A":"Rules","B":"Threats","C":"CMDB Entries","D":"Incidents","E":"Procedures"},"answer":["A","D"],"image":null,"correctCount":2},{"id":26,"text":"What will happen when a device being analyzed by the machine learning (ML) configuration shown in the exhibit has a consistently high memory use? (Choose one answer)","options":{"A":"FortiSIEM will update the regression tables for memory use, and average sent and received bytes.","B":"FortiSIEM will update the model with a higher memory use average value.","C":"FortiSIEM will Lower the CPU use trigger requirement for CPU use.","D":"FortiSIEM will trigger an incident for high memory use."},"answer":["B"],"image":"assets-fortisiem-q026.jpg","correctCount":1},{"id":27,"text":"Which event type attribute value will the FortiSIEM parser save for this event? (Choose one answer)","options":{"A":"PH_DEV_MON_SYS_UPTIME","B":"PHL_INFO","C":"phLogDetail","D":"sysUpTime"},"answer":["A"],"image":"assets-fortisiem-q027.jpg","correctCount":1},{"id":28,"text":"How can an administrator restrict the application of an automation policy on FortiSIEM? (Choose two answers)","options":{"A":"Apply the automation policy to a specific Incident and Incident Groups","B":"Apply the automation policy to specific Rules and Rule Groups","C":"Apply the automation policy to specific Event Types","D":"Apply the automation policy to specific Organizations"},"answer":["B","D"],"image":null,"correctCount":2},{"id":29,"text":"Which information will this analytics search display? (Choose one answer)","options":{"A":"Failed machine login events with a source IP address of servers in the Device IP report","B":"Failed login events from all servers in the Server Inventory configuration management database (CMDB) report","C":"Failed login events from all servers defined in the CMDB","D":"All servers in the Logon Failure user group"},"answer":["B"],"image":"assets-fortisiem-q029.jpg","correctCount":1},{"id":30,"text":"An analyst wants to create a rule from a new analytic search they just performed. Which method is the most efficient way for you to create the rule? (Choose one answer)","options":{"A":"Make a new rule using the Create Rule option in the Actions menu.","B":"Manually re-create the analytics search in the rule configuration.","C":"Save the search as a template, and create a new rule from the template.","D":"Copy and paste the raw analytics search text into a rule subpattern."},"answer":["A"],"image":null,"correctCount":1},{"id":31,"text":"You want FortiSIEM to automatically add three zero trust network access (ZTNA) tags to a device when that device triggers a custom rule. You want FortiSIEM to push these ZTNA tags to multiple FortiClient EMS servers in the organization. How can you accomplish this? (Choose one answer)","options":{"A":"Create a single playbook with multiple connectors, one for each FortiClient EMS.","B":"Create multiple automation policies, each one pushing a tag to a different FortiClient EMS server.","C":"Create multiple playbooks, one for each FortiClient EMS server, each with a connector for a ZTNA tag.","D":"Create a syslog connection from the FortiClient EMS servers to retrieve ZTNA tag information from FortiSIEM."},"answer":["A"],"image":null,"correctCount":1},{"id":32,"text":"An analyst wants to perform a KMeans machine learning (ML) job on this data. How many N clusters would be a good fit for the data? (Choose one answer)","options":{"A":"Two","B":"50","C":"100","D":"One"},"answer":["A"],"image":"assets-fortisiem-q032.jpg","correctCount":1},{"id":33,"text":"Why is this search not producing any results? (Choose one answer)","options":{"A":"There is a nested query attribute type mismatch.","B":"You cannot reference both the User and Event Type attributes in the same analytics search.","C":"You did not use the configuration management database (CMDB) group search properly.","D":"You must set the Time Range to Real-time to identify login failures.","E":"You must set the Operator to = for both queries."},"answer":["A"],"image":"assets-fortisiem-q033.jpg","correctCount":1},{"id":34,"text":"Rules on FortiSIEM are usually processed as events are collected (streaming). How can you create a rule to evaluate events over an 8-hour period? (Choose one answer)","options":{"A":"Configure a crontab process on the FortiSIEM supervisor.","B":"Configure a report to run the analytical query and run the report every 8 hours.","C":"Set the Evaluation Mode to Scheduled under the General tab.","D":"Configure a 28,000-second time window under the Define Conditions tab."},"answer":["C"],"image":null,"correctCount":1},{"id":35,"text":"What is one difference between a lookup table and a watchlist? (Choose one answer)","options":{"A":"Watch list entries do not expire, lookup table entries have a defined lifetime.","B":"A lookup table requires a parser to be able to query and interpret the data, a watchlist does not require a parser.","C":"A lookup table can have multiple columns, and a watchlist only has one.","D":"A watchlist can be updated through an API, and a lookup table cannot."},"answer":["C"],"image":null,"correctCount":1},{"id":36,"text":"Which two things happen when this automation policy triggers? (Choose two answers)","options":{"A":"No notification or remediation is performed.","B":"A remediation script is run.","C":"A clear notification is sent to the SOC manager dashboard.","D":"An email is sent to the defined email."},"answer":["B","D"],"image":"assets-fortisiem-q036.jpg","correctCount":2},{"id":37,"text":"According to the automation policy configuration shown in the exhibit, what happens if an associated rule triggers? (Choose one answer)","options":{"A":"FortiSIEM runs the remediation script.","B":"FortiSIEM sends an email.","C":"FortiSIEM executes all the actions.","D":"FortiSIEM runs everything except the playbook, because the playbook and the remediation script perform similar functions."},"answer":["C"],"image":"assets-fortisiem-q037.jpg","correctCount":1},{"id":38,"text":"Which two actions can you select in an automation policy to trigger an API call to block an IP address on a FortiGate? (Choose two answers)","options":{"A":"Open Remedy ticket using the configuration set in","B":"Send Email/SMS/Webhook to the target users","C":"Invoke an Integration Policy","D":"Run Remediation/Script","E":"Run Playbook on Incident Trigger"},"answer":["D","E"],"image":"assets-fortisiem-q038.jpg","correctCount":2},{"id":39,"text":"Why would the two entries shown in the exhibit be included in an incident activity history? (Choose one answer)","options":{"A":"Multiple new incidents have occurred and has triggered the rule threshold.","B":"An analyst resolved and cleared the incident and the Do not notify when an incident is cleared by system option is not enabled in the automation policy.","C":"The system cleared the incident and is configured to Send Email/SMS/Webhook to the target users.","D":"An administrator has enabled the Notify on Incident Cleared option."},"answer":["C"],"image":"assets-fortisiem-q039.jpg","correctCount":1},{"id":40,"text":"You are troubleshooting why the rule shown in the exhibit is generating incidents for successful Remote Desktop Protocol (RDP) connections with correct Logins. It should only be triggering when a person fails a login three or more times to the target device when connecting with RDP. What is causing the rule to be triggered by correct login events? (Choose one answer)","options":{"A":"The subpattern relationship RDP_Connection:User = Failed_Logon:User never matches.","B":"The Boolean between the subpatterns is incorrect.","C":"The attribute types in the subpatterns do not match.","D":"The RDP login is different from the login used to access the target device."},"answer":["B"],"image":"assets-fortisiem-q040.jpg","correctCount":1},{"id":41,"text":"You need a model that predicts a target field based on other fields in a dataset and then triggers an anomaly if the value does not match the prediction. Which machine learning (ML) algorithm will you use to build this type of model? (Choose one answer)","options":{"A":"Regression","B":"Forecasting","C":"Classification","D":"Anomaly detection"},"answer":["A"],"image":null,"correctCount":1},{"id":42,"text":"When using user and entity behavior analytics (UEBA) on FortiSIEM, what can you use to dynamically supply a list of suspicious IP addresses to FortiGate for blocking? (Choose one answer)","options":{"A":"The Fortinet Security Fabric","B":"Secure Copy Protocol (SCP)","C":"FortiSIEM watchlists","D":"FortiSIEM lookup tables"},"answer":["C"],"image":null,"correctCount":1},{"id":43,"text":"Which rule Logic should you use to apply a user entity and behavior analytics (UEBA) tag to an event for a failed login incident by the account JSmith? (Choose one answer)","options":{"A":"User CONTAIN smith","B":"Username IS jsmith","C":"User = smith","D":"Username START WITH smith"},"answer":["B"],"image":null,"correctCount":1},{"id":44,"text":"What are two required components in a rule? (Choose two answers)","options":{"A":"Tag","B":"Clear policy","C":"Subpattern","D":"Detection technology"},"answer":["C","D"],"image":null,"correctCount":2},{"id":45,"text":"Three events are collected over 10 minutes from two servers: Server A and Server B. Based on the settings for the rule subpattern and a 10-minute condition window, how many incidents will the servers generate? (Choose one answer)","options":{"A":"Server A will generate one incident and Server B will not generate any incidents.","B":"Server A will not generate any incidents and Server B will not generate any incidents.","C":"Server A will generate three incidents and server B will generate one incident.","D":"Server A will generate one incident and Server B will generate one incident."},"answer":["A"],"image":"assets-fortisiem-q045.jpg","correctCount":1},{"id":46,"text":"You want to create a rule with multiple subpatterns but trigger an incident only if three different subpatterns are matched over a 24-hour period. Where must you define the time period that the rule uses to evaluate all the subpatterns? (Choose one answer)","options":{"A":"Define the time window in each individual subpattern.","B":"Define the time window under the General tab of the rule.","C":"Define the time window under the Define Condition tab of the rule.","D":"Define the time window in the Define Action section of the rule."},"answer":["C"],"image":null,"correctCount":1},{"id":47,"text":"An analyst wants to run a remediation playbook when a user fails a VPN login five times from an external machine. Where do they associate the remediation playbook with the triggering rule? (Choose one answer)","options":{"A":"In an automation policy","B":"In the associated playbook under Remediation","C":"In the associated rule under Action","D":"In an incident policy"},"answer":["A"],"image":null,"correctCount":1},{"id":48,"text":"You are attempting to tune an anomaly detection machine learning (ML) job. The chart shows there are no anomalies detected, but you are not satisfied with the fit of the ML model. Which adjustment must you make to train the model and ensure a better fit? (Choose one answer)","options":{"A":"Decrease the Multiplier.","B":"Increase the number of Windows.","C":"Increase the Multiplier.","D":"Decrease the number of Windows."},"answer":["A"],"image":"assets-fortisiem-q048.jpg","correctCount":1},{"id":49,"text":"You want the rule shown in the exhibit to trigger when three failed login attempts occur within 3 minutes. Which condition time window and aggregate values are correct for your objective? (Choose one answer)","options":{"A":"Time window 180 seconds, aggregate value 3","B":"Time window 180 seconds, aggregate value 2","C":"Time window 540 seconds, aggregate value 3","D":"Time window 60 seconds, aggregate value 3"},"answer":["B"],"image":"assets-fortisiem-q049.jpg","correctCount":1},{"id":50,"text":"If you group these events by the User and Count attributes, how many unique results will FortiSIEM display? (Choose one answer)","options":{"A":"Four","B":"Six","C":"Five","D":"Three"},"answer":["C"],"image":"assets-fortisiem-q050.jpg","correctCount":1},{"id":51,"text":"How can you use the configuration management database (CMDB) in an analytics search? (Choose one answer)","options":{"A":"Use device IP addresses defined in the CMDB to perform an nmap analytics scan.","B":"Match passwords defined in the CMDB to Look for suspicious logins.","C":"Use devices defined in the CMDB as source IP addresses.","D":"Perform an AI-assisted analytics search using devices defined in the CMDB."},"answer":["C"],"image":null,"correctCount":1},{"id":52,"text":"An incorrect configuration is shown. Which setting must you change to successfully apply this configuration to FortiSIEM? (Choose one answer)","options":{"A":"Select the same values in the Fields to use for Prediction and Field to Predict sections.","B":"Set the Run Mode to ML.","C":"Set the Train factor to 70% or greater.","D":"Set the algorithm to Anomaly Detection."},"answer":["C"],"image":"assets-fortisiem-q052.jpg","correctCount":1},{"id":53,"text":"Which two ways are rule tags used on FortiSIEM? (Choose two answers)","options":{"A":"Event searches","B":"Playbook filtering","C":"Zero trust network access (ZTNA) enforcement on FortiClient EMS","D":"Administrative user permissions"},"answer":["A","B"],"image":null,"correctCount":2},{"id":54,"text":"If you apply this Group By and Display Fields configuration to a list of network connections, which information will FortiSIEM display? (Choose one answer)","options":{"A":"A running count of connections, regardless of their source and destination","B":"A list of connections ordered by the number of unique connections started by each unique source IP address","C":"A list of connections between unique source and destination IP addresses","D":"A list of connections ordered by the total amount of data sent between unique devices"},"answer":["C"],"image":"assets-fortisiem-q054.jpg","correctCount":1},{"id":55,"text":"Which statement about the time range settings defined in the nested query is accurate? (Choose one answer)","options":{"A":"FortiSIEM will list source IP addresses found the last 10 minutes of events from each day in the Approved Devices report from the Last 30 days.","B":"FortiSIEM will search in real time using 10 minute blocks for a source IP address that is not in the Approved Devices report from the last 30 days.","C":"FortiSIEM will search the Last 30 days of events for a source IP address that is not in the Approved Devices report.","D":"FortiSIEM will search the Last 10 minutes of events for a source IP address that is not in the Approved Devices report from the last 30 days."},"answer":["D"],"image":"assets-fortisiem-q055.jpg","correctCount":1},{"id":56,"text":"In an automation policy, which two methods can you use for notifications when an incident is triggered? (Choose two answers)","options":{"A":"GUI pop-up window","B":"Email","C":"SNMP trap","D":"Assigned FortiSIEM case"},"answer":["B","D"],"image":null,"correctCount":2},{"id":57,"text":"What are four incident'status options on FortiSIEM? (Choose one answer)","options":{"A":"Active, cleared, false negative, false positive","B":"Active, auto cleared, cleared manually, system cleared","C":"Active, auto closed, closed manually, system closed","D":"Active, closed, cleared, resolved"},"answer":["B"],"image":null,"correctCount":1},{"id":58,"text":"You are creating a rule to fill a gap in your organization's MITRE ATT&CK rule coverage matrix. How can you associate the rule with an appropriate tactics, techniques and procedures (TTP) category? (Choose one answer)","options":{"A":"Assign the TTP category to one of the incidents generated by the rule.","B":"Add the rule directly in the Rule Coverage matrix under the appropriate TTP section.","C":"Configure the appropriate TTP category in the Define Action section of the rule.","D":"Assign the TTP category in the aggregate section of the rule subpattern."},"answer":["C"],"image":null,"correctCount":1},{"id":59,"text":"When configuring machine learning (ML), in which step can you modify how the model fits the training data set? (Choose one answer)","options":{"A":"Prepare Data","B":"Train","C":"Statistics","D":"Design"},"answer":["B"],"note":"","image":null,"correctCount":1},{"id":60,"text":"Which three types of data can you use to train FortiSIEM machine learning (ML)? (Choose three answers)","options":{"A":"CSV files","B":"FortiSIEM analytical reports","C":"FortiSIEM ML job","D":"SQL database","E":"Configuration management database (CMDB)"},"answer":["A","B","C"],"image":null,"correctCount":3},{"id":61,"text":"A critical server is sending traffic that is triggering a high severity outbound intrusion prevention system (IPS) permitted IPS exploit rule. This traffic must be allowed. Which two items must you configure to prevent this server from triggering the incident? (Choose two answers)","options":{"A":"Modify the group by parameters to exclude the IP address.","B":"Modify the subpattern filter to exclude the IP address.","C":"Modify the aggregate count in the subpattern.","D":"Create a rule exception for the IP address.","E":"Change the time window on the rule conditions."},"answer":["B","D"],"image":null,"correctCount":2},{"id":62,"text":"Which two processes run analytical queries and must always be running to perform searches? (Choose two answers)","options":{"A":"phAnomalyMaster","B":"phQueryWorker","C":"phRuleWorker","D":"phQueryMaster","E":"phRuleMaster"},"answer":["B","D"],"image":null,"correctCount":2},{"id":63,"text":"Which value will the FortiSIEM parser use to populate the Application Name field? (Choose one answer)","options":{"A":"Network.Service: SSL","B":"Network Service","C":"SSL","D":"Network.Service"},"answer":["C"],"image":"assets-fortisiem-q063.jpg","correctCount":1},{"id":64,"text":"Which two types of information can FortiSIEM retrieve from FortiClient EMS through an external connection? (Choose two answers)","options":{"A":"Zero trust network access (ZTNA) tags","B":"Vulnerability scan events","C":"Device login credentials","D":"Devices with FortiSIEM agents"},"answer":["A","B"],"image":null,"correctCount":2},{"id":65,"text":"You are investigating an issue with two destination IP addresses, but you are not getting any results from the search. Based on the filters shown in the exhibit, why is this search returning no results? (Choose one answer)","options":{"A":"You are using the wrong Boolean operator in the Next column.","B":"The two items are not grouped in parentheses ().","C":"You are using an invalid IP address in the Value column.","D":"You are using an incorrect entry in the Operator column."},"answer":["A"],"image":"assets-fortisiem-q065.jpg","correctCount":1},{"id":66,"text":"Which statement about the nested query shown in the exhibit is true? (Choose one answer)","options":{"A":"The outer query could have also referenced the Protocol field from the inner query.","B":"The outer query should have used the operator CONTAINS when referencing the inner query.","C":"The outer query could have also referenced the Reporting IP address field from the inner query.","D":"The outer query could have referenced all the queried fields from the inner query."},"answer":["C"],"image":"assets-fortisiem-q066.jpg","correctCount":1},{"id":67,"text":"If you group these events by the Reporting Device , Reporting IP , and Event Type attributes, how many unique results will FortiSIEM display? (Choose one answer)","options":{"A":"Three","B":"Zero","C":"One","D":"Six"},"answer":["C"],"image":"assets-fortisiem-q067.jpg","correctCount":1},{"id":68,"text":"You want to build an event query that displays only events to higher-numbered destination ports (1024-65535). Which analytic search string is valid for this scenario? (Choose one answer)","options":{"A":"Destination TCP/UDP Port > 1024","B":"Destination TCP/UDP Port BETWEEN 1024-65535","C":"Destination TCP/UDP Port >= 1024 AND Destination TCP/UDP Port <= 65535","D":"Destination TCP/UDP Port = 1024-65535"},"answer":["C"],"image":null,"correctCount":1},{"id":69,"text":"What is this rule attempting to match? (Choose one answer)","options":{"A":"Failed VPN logon attempts from three or more different outside countries.","B":"Failed VPN logon events from a source outside the home country.","C":"Failed VPN logon attempts from three or more different sources inside the home country.","D":"Excessive VPN logon failures from a source inside the home country."},"answer":["A"],"note":"У записі голосування показує B, але поле Correct Answer містить A. Для перевірки використано поле Correct Answer.","image":"assets-fortisiem-q069.jpg","correctCount":1},{"id":70,"text":"Which three steps can you reference multiple times in a playbook? (Choose three answers)","options":{"A":"Decision","B":"Automation Policy Trigger","C":"Connector","D":"Set Variable"},"answer":["A","C","D"],"image":null,"correctCount":3},{"id":71,"text":"Which statement about FortiSIEM performance threshold metrics is true? (Choose one answer)","options":{"A":"FortiSIEM has customizable global and individual device thresholds for performance metrics.","B":"FortiSIEM has hardcoded global and customizable individual device thresholds for performance metrics.","C":"FortiSIEM uses hardcoded global and device thresholds for all performance metrics.","D":"FortiSIEM uses only global thresholds for performance metrics."},"answer":["A"],"image":null,"correctCount":1},{"id":72,"text":"If you group these events by the Reporting IP, Event Type, and User attributes, how many results will FortiSIEM display? (Choose one answer)","options":{"A":"Two","B":"Three","C":"Six","D":"Five"},"answer":["B"],"image":"assets-fortisiem-q072.jpg","correctCount":1},{"id":73,"text":"What does the Group: Windows value refer to? (Choose one answer)","options":{"A":"A Windows Active Directory (AD) user group","B":"A SOC analyst group","C":"A FortiSIEM user group","D":"A configuration management database (CMDB) device group"},"answer":["D"],"image":"assets-fortisiem-q073.jpg","correctCount":1},{"id":74,"text":"Which two conditions will match this rule and subpatterns? (Choose two answers)","options":{"A":"A user connects to the wrong IP address for an RDP session five times with saved credentials.","B":"A user runs a brute force password cracker against an RDP server.","C":"A user using RDP over SSL VPN fails to log in to an application five times.","D":"A user fails twice to log in when connecting through Remote Desktop Protocol (RDP)."},"answer":["B","C"],"note":"У записі голосування показує B,D, але поле Correct Answer містить B,C. Для перевірки використано поле Correct Answer.","image":"assets-fortisiem-q074.jpg","correctCount":2},{"id":75,"text":"You are trying to generate an incident with a title that includes Source IP, Destination IP, User, and Destination TCP/UDP Port. You are unable to add Destination TCP/UDP Port as an incident attribute. Which change must you make? (Choose one answer)","options":{"A":"Select Destination TCP/UDP Port as a triggering attribute in the rule.","B":"Set Destination TCP/UDP Port as an aggregate item in the subpattern.","C":"Add Destination TCP/UDP Port as an event type.","D":"Remove the Destination IP event attribute."},"answer":["B"],"image":"assets-fortisiem-q075.jpg","correctCount":1},{"id":76,"text":"Several new internal servers are generating incidents and must be excluded from several FortiSIEM rules. How must you tune rules to exclude several undiscovered devices from rules? (Choose one answer)","options":{"A":"Add them to a device group that is being filtered by the rules.","B":"Add the devices to a rule exclusion automation policy.","C":"Add their associated discovery credentials.","D":"Add them to the global exclusion list"},"answer":["A"],"image":null,"correctCount":1}]}];
